  const ldq = { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: FAQ.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: stripTags(a) } })) };
  files.set('/faq/index.html', layout({ title: 'Questions fréquentes : livraison, paiement, devis | ' + NAME, desc: clip('Devis, délais de livraison, paiement comptant ou échelonné, installation, autorisations : les réponses aux questions sur l’achat d’un mobil-home chez ' + NAME + '.', 158), path: '/faq/', body: h, jsonld: [ldq], alt: { fr: '/faq/', en: '/en/faq/' } }));
